do(Ver, Data, Ext) ->
    case Ver =:= 76 andalso is_record(Data, role) of
        false ->
            logger:info("Ver:~w, Data:~w",
                        [Ver, Data],
                        role_data_convert,
                        2820),
            logger:error("角色数据项不匹配, 转换失败",
                         [],
                         role_data_convert,
                         2821),
            {error, role_data_convert_failure};
        true ->
            NewData = modify_ext(Data, Ext),
            parse_field([agenda,
                         eqm,
                         attr,
                         pet,
                         pet_store,
                         guard,
                         classes_challenge,
                         m_attr_point,
                         quest,
                         goal,
                         friend,
                         assets,
                         buff,
                         checkin,
                         investment,
                         wing,
                         fashion,
                         achievement,
                         achieve_shop,
                         combat,
                         arena,
                         trial,
                         skill,
                         limit_return,
                         campaign,
                         skill_life,
                         combat_hook_setting,
                         mount,
                         handbook,
                         extension,
                         m_wedding,
                         endless_challenge,
                         constellation,
                         examination,
                         reward_back,
                         maze,
                         dungeon,
                         guild,
                         alchemy,
                         talisman,
                         child,
                         tournament,
                         privilege,
                         glory,
                         exquisite_shelf,
                         m_camp_recharge,
                         honor,
                         head,
                         m_gods_duel,
                         m_gods_place,
                         m_camp_sign_draw,
                         m_teacher,
                         m_provocation,
                         m_oracle_treasure,
                         m_camp_pray],
                        NewData)
    end.

modify_ext(Data, []) -> Data;
modify_ext(Data, [{lock_status, LockStatus} | T]) ->
    modify_ext(Data#role{lock_status = LockStatus}, T);
modify_ext(Data, [{name, Name} | T]) ->
    modify_ext(Data#role{name = Name}, T);
modify_ext(Data, [{label, Label} | T]) ->
    modify_ext(Data#role{label = Label}, T).

-spec parse_field([Type :: atom()],
                  Data :: #role{}) -> {ok, #role{}} |
                                      {error, role_data_convert_failure}.

parse_field([], Role) -> {ok, Role};
parse_field([Field | T], Role) ->
    case parse_field(Field, Role) of
        {error, _Reason} ->
            logger:error("版本转换失败：~ts",
                         [_Reason],
                         role_data_convert,
                         2853),
            {error, role_data_convert_failure};
        {ok, NewRole} -> parse_field(T, NewRole)
    end;
parse_field(agenda, Role = #role{m_agenda = Field}) ->
    case agenda_ver:do(Field) of
        {false, Reason} -> {error, Reason};
        {ok, NewField} -> {ok, Role#role{m_agenda = NewField}}
    end;
parse_field(eqm,
            Role = #role{p_eqm = Eqm = #package{items = Items}}) ->
    NewItems =
        [blacksmith:update_max_enchant_lev(eqm_attr:calc_eqm(Item))
         || Item <- Items],
    {ok, Role#role{p_eqm = Eqm#package{items = NewItems}}};
parse_field(attr, Role = #role{attr = Attr}) ->
    case attr_ver:do(Attr) of
        {ok, NewAttr} -> {ok, Role#role{attr = NewAttr}};
        {false, Reason} -> {error, Reason}
    end;
parse_field(m_attr_point,
            Role = #role{lev = Lev, m_attr_point = MattrPoint}) ->
    case attr_ver:do_point(MattrPoint, Lev) of
        {ok, NewMattrPoint} ->
            {ok, Role#role{m_attr_point = NewMattrPoint}};
        {false, Reason} -> {error, Reason}
    end;
parse_field(pet, Role = #role{m_pet = MPet}) ->
    case pet_ver:do(MPet) of
        {error, Reason} -> {error, Reason};
        {ok, NewMPet} -> {ok, Role#role{m_pet = NewMPet}}
    end;
